#!/usr/bin/env node
/**
 * Generates web/lib/api/schema.ts, the TypeScript types for the API, from the FastAPI OpenAPI
 * document (plan.md T0.7). The API is the contract; the generated file is never edited by hand.
 *
 *   pnpm gen:api           regenerate the file
 *   pnpm gen:api --check   exit 1 if the committed file is out of date (used by CI and pre-commit)
 *
 * Needs `uv` on PATH. It runs `python -m app.cli export-openapi` in ../api, which needs no
 * environment variables and no running services.
 */
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import openapiTS, { astToString } from "openapi-typescript";

const webDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const apiDir = path.resolve(webDir, "..", "api");
const target = path.join(webDir, "lib", "api", "schema.ts");

const BANNER = [
  "// Generated by `pnpm gen:api` from the API's OpenAPI document. Do not edit by hand:",
  "// change the API, then run `pnpm gen:api`. CI fails if this file is out of date.",
  "",
].join("\n");

function exportOpenApi() {
  try {
    return JSON.parse(
      execFileSync(
        "uv",
        ["run", "--quiet", "--directory", apiDir, "python", "-m", "app.cli", "export-openapi"],
        {
          encoding: "utf8",
          maxBuffer: 64 * 1024 * 1024,
          stdio: ["ignore", "pipe", "inherit"],
        },
      ),
    );
  } catch (error) {
    console.error(
      "gen-api: could not export the OpenAPI document from ../api (is `uv` installed?).",
    );
    throw error;
  }
}

const document = exportOpenApi();
const generated = `${BANNER}${astToString(await openapiTS(document))}`;

if (process.argv.includes("--check")) {
  const current = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (current === generated) {
    console.log("gen-api: lib/api/schema.ts is up to date.");
    process.exit(0);
  }
  console.error(
    "gen-api: lib/api/schema.ts is OUT OF DATE. Run `pnpm gen:api` and commit the result.",
  );
  process.exit(1);
}

writeFileSync(target, generated);
console.log(
  `gen-api: wrote ${path.relative(webDir, target)} (${generated.split("\n").length} lines).`,
);
